/// Undoes the accumulated lane-0 rescaling for width 13, applied
/// once after the last partial round.
pub static LAMBDA_END_13: Fr = Fr::new(BigInteger256::new([
    3952352259520608162,
    1986203873269899597,
    14289866373499462820,
    451788087736571687,
]));

/// Returns the sparse-MDS decomposition of the partial rounds for width
/// `t`, or `None` when no decomposition is bundled for that width.
pub fn get_sparse_mds_parameters(t: u8) -> Option<SparseMdsParameters<Fr>> {
    match t {
        2 => Some(SparseMdsParameters::new_unchecked(
            &PRE_2,
            &SPARSE_2,
            &PARTIAL_ARK_2,
            &POST_2,
            &LAMBDA_END_2,
        )),
        3 => Some(SparseMdsParameters::new_unchecked(
            &PRE_3,
            &SPARSE_3,
            &PARTIAL_ARK_3,
            &POST_3,
            &LAMBDA_END_3,
        )),
        4 => Some(SparseMdsParameters::new_unchecked(
            &PRE_4,
            &SPARSE_4,
            &PARTIAL_ARK_4,
            &POST_4,
            &LAMBDA_END_4,
        )),
        5 => Some(SparseMdsParameters::new_unchecked(
            &PRE_5,
            &SPARSE_5,
            &PARTIAL_ARK_5,
            &POST_5,
            &LAMBDA_END_5,
        )),
        6 => Some(SparseMdsParameters::new_unchecked(
            &PRE_6,
            &SPARSE_6,
            &PARTIAL_ARK_6,
            &POST_6,
            &LAMBDA_END_6,
        )),
        7 => Some(SparseMdsParameters::new_unchecked(
            &PRE_7,
            &SPARSE_7,
            &PARTIAL_ARK_7,
            &POST_7,
            &LAMBDA_END_7,
        )),
        8 => Some(SparseMdsParameters::new_unchecked(
            &PRE_8,
            &SPARSE_8,
            &PARTIAL_ARK_8,
            &POST_8,
            &LAMBDA_END_8,
        )),
        9 => Some(SparseMdsParameters::new_unchecked(
            &PRE_9,
            &SPARSE_9,
            &PARTIAL_ARK_9,
            &POST_9,
            &LAMBDA_END_9,
        )),
        10 => Some(SparseMdsParameters::new_unchecked(
            &PRE_10,
            &SPARSE_10,
            &PARTIAL_ARK_10,
            &POST_10,
            &LAMBDA_END_10,
        )),
        11 => Some(SparseMdsParameters::new_unchecked(
            &PRE_11,
            &SPARSE_11,
            &PARTIAL_ARK_11,
            &POST_11,
            &LAMBDA_END_11,
        )),
        12 => Some(SparseMdsParameters::new_unchecked(
            &PRE_12,
            &SPARSE_12,
            &PARTIAL_ARK_12,
            &POST_12,
            &LAMBDA_END_12,
        )),
        13 => Some(SparseMdsParameters::new_unchecked(
            &PRE_13,
            &SPARSE_13,
            &PARTIAL_ARK_13,
            &POST_13,
            &LAMBDA_END_13,
        )),
        _ => None,
    }
}
